#include "RegisterSourceTransitions.h"
#include <iostream>
#include <stdexcept>
#include <stop_token>
using namespace dft::sequential;
static unsigned n=0;static void need(bool v,const char* m){++n;if(!v)throw std::runtime_error(m);}
static void bad(const auto& r,const char* m){need(!r&&r.error().code==hier::ErrorCode::BadRequest,m);}
static auto open(const char* f,const char* top){hier::model::OpenOptions o;o.files={f};o.tops={top};auto r=hier::Design::open(o);need(r.ok(),"open own RTL");return std::move(r.value());}
static auto request(const char* top){RegisterScenarioRequest r;r.common.resolveLogic=true;std::string p=std::string(top)+".mode";r.scenarios={{"ZERO",{{{p,0},false}}},{"ONE",{{{p,0},true}}},{"BACK",{{{p,0},false}}}};return r;}
int main(int argc,char** argv){try{
 need(argc==2,"fixture");auto d=open(argv[1],"V_swap");StatisticsRequest rq;rq.scope="V_swap.u";auto st=registerStatistics(*d,rq);need(st.ok()&&st->complete,"original statistics");auto req=request("V_swap");std::stop_source stop;stop.request_stop();
 auto dc=compareRegisterSourceDeltas(*d,*st,req,{},stop.get_token());need(!dc&&dc.error().code==hier::ErrorCode::Cancelled,"delta pre-cancel");auto ac=compareRegisterSourceAttribution(*d,*st,req,{},stop.get_token());need(!ac&&ac.error().code==hier::ErrorCode::Cancelled,"attribution pre-cancel");auto tc=compareRegisterSourceTransitions(*d,*st,req,{},stop.get_token());need(!tc&&tc.error().code==hier::ErrorCode::Cancelled,"transition pre-cancel");
 RegisterSourceDeltaLimits dl;dl.maxRows=0;bad(compareRegisterSourceDeltas(*d,*st,req,dl),"delta bad limits");RegisterSourceAttributionLimits al;al.maxMembers=0;bad(compareRegisterSourceAttribution(*d,*st,req,al),"attribution bad limits");RegisterSourceTransitionLimits tl;tl.maxSources=0;bad(compareRegisterSourceTransitions(*d,*st,req,tl),"transition bad limits");auto stale=*st;stale.snapshot.snapshotId+="wrong";
 bad(compareRegisterSourceDeltas(*d,stale,req),"delta stale snapshot");bad(compareRegisterSourceAttribution(*d,stale,req),"attribution stale snapshot");bad(compareRegisterSourceTransitions(*d,stale,req),"transition stale snapshot");auto br=req;br.scenarios[1].inputValues[0].input.path="missing";
 need(!compareRegisterSourceDeltas(*d,*st,br),"delta second context no half success");need(!compareRegisterSourceAttribution(*d,*st,br),"attribution second context no half success");need(!compareRegisterSourceTransitions(*d,*st,br),"transition second context no half success");
 auto de=compareRegisterSourceDeltas(*d,*st,req);need(de.ok()&&de->complete&&de->rows.size()==4,"delta reuse and complete comparison prefix");
 for(const auto& row:de->rows){need(row.delta.has_value(),"decided row delta");const auto& x=row.delta->totals;if(row.scenario==1)need(x.addedBits+x.removedBits==5&&x.retainedBits==4,"per source symmetric swap5/retained4");else need(x.addedBits==0&&x.removedBits==0,"0/1/0 restored source coverage");}
 auto at=compareRegisterSourceAttribution(*d,*st,req);need(at.ok()&&at->complete&&at->comparisons.size()==2,"attribution reusable");need(at->comparisons[0].totals.coveredBits==9&&at->comparisons[0].totals.changedBits==5&&at->comparisons[0].totals.retainedOnlyBits==4,"attribution unique9 changed5 retained4");need(at->comparisons[1].totals.changedBits==0&&at->comparisons[1].totals.retainedOnlyBits==9,"return to baseline retains9");
 auto tr=compareRegisterSourceTransitions(*d,*st,req);need(tr.ok()&&tr->complete&&tr->comparisons[0].cohorts.size()==3,"three exact source-set conversions");need(tr->comparisons[0].totals.coveredBits==9&&tr->comparisons[0].totals.changedBits==5,"cohort totals count each bit once");
 dl={};dl.maxRanges=1;auto pd=compareRegisterSourceDeltas(*d,*st,req,dl);need(pd.ok()&&!pd->complete&&pd->rows.empty()&&pd->ranges==0&&pd->signals==0,"whole delta source row");al={};al.maxIntervals=1;auto pa=compareRegisterSourceAttribution(*d,*st,req,al);need(pa.ok()&&!pa->complete&&!pa->comparisons[0].inputCollected&&pa->intervals==0&&pa->comparisons[0].rows.empty(),"no partially collected source index");tl={};tl.maxSources=1;auto pt=compareRegisterSourceTransitions(*d,*st,req,tl);need(pt.ok()&&!pt->complete&&pt->cohorts==0&&pt->members==0&&pt->sources==0,"whole cohort source/member/count publication");
 d.reset();st=hier::Error{hier::ErrorCode::BadRequest,"released"};need(de->rows[0].delta->signals.size()==1&&at->comparisons[0].rows[0].segments.size()==3&&!tr->analysis.analysis.analysis.rows[0].source.kind.empty(),"three returned report chains own values after inputs released");
 auto sets=open(argv[1],"V_sets");rq.scope="V_sets";auto ss=registerStatistics(*sets,rq);need(ss.ok(),"two-signal statistics");auto sr=compareRegisterSourceTransitions(*sets,*ss,request("V_sets"));need(sr.ok()&&sr->complete&&sr->comparisons[0].cohorts.size()==1,"multi-source conversion one cohort");const auto& co=sr->comparisons[0].cohorts[0];need(co.baselineSources.size()==2&&co.scenarioSources.size()==2&&co.members.size()==2&&co.counts.coveredBits==8&&co.counts.changedBits==8,"complete many-to-many sets and two members8bits");need(!sr->comparisons[1].cohorts[0].changed&&sr->comparisons[1].totals.retainedOnlyBits==8,"multi-source0/1/0 isolation");
 sets.reset();ss=hier::Error{hier::ErrorCode::BadRequest,"released"};need(sr->comparisons[0].cohorts[0].members.size()==2,"cohort member container owns after Design/statistics release");std::cout<<"{\"passed\":true,\"assertions\":"<<n<<"}\n";return 0;
 }catch(const std::exception& e){std::cerr<<"after "<<n<<" assertions: "<<e.what()<<'\n';return 1;}}
